require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/helpers.php';requerirRol(['departamento']);
requerirCorreoConfirmado($pdo);$u=usuarioActual();$id=(int)($_GET['id']??0);$q=$pdo->prepare("SELECT t.*,d.nombre AS departamento,TRIM(CONCAT(COALESCE(p.nombre,''),' ',COALESCE(p.apellido,''))) AS analista FROM tickets t JOIN departamentos d ON d.id_departamentos=t.departamento_id LEFT JOIN usuarios a ON a.id_usuarios=t.analista_id LEFT JOIN perfiles_usuarios p ON p.usuario_id=a.id_usuarios WHERE t.id_tickets=? AND t.departamento_id=? LIMIT 1");$q->execute([$id,$u['departamento_id']]);$t=$q->fetch();if(!$t){header('Location: mis_tickets.php');exit;}?><!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ticket #<?=str_pad((string)$id,6,'0',STR_PAD_LEFT)?></title><link rel="icon" href="../assets/img/logo.png"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet" integrity="sha384-QWTKZyjpPEjISv5WaRU9OFeRpok6YctnYmDr5pNlyT2bRjXh0JMhjY6hW+ALEwIH" crossorigin="anonymous"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet" integrity="sha384-tViUnnbYAV00FLIhhi3v/dWt3Jxw4gZQcNoSCxCIFNJVCx7/D55/wXsrNIRANwdD" crossorigin="anonymous"><link href="../assets/css/style.css" rel="stylesheet"></head><body><div class="app-shell"><?php include __DIR__ . '/../includes/sidebar.php'; ?><div class="main"><?php include __DIR__.'/../includes/topbar.php'; ?><div class="content"><div class="card-panel" style="max-width:850px"><div class="panel-head"><h2>Ticket #<?=str_pad((string)$id,6,'0',STR_PAD_LEFT)?></h2><span class="badge badge-proceso"><?=h(ucfirst(str_replace('_',' ',$t['estado'])))?></span></div><div class="panel-body"><h3 class="fs-5"><?=h($t['titulo'])?></h3><p class="text-muted mb-4"><?=nl2br(h($t['descripcion']))?></p><div class="row g-3"><div class="col-md-6"><strong>Departamento</strong><div><?=h($t['departamento'])?></div></div><div class="col-md-6"><strong>Solicitante</strong><div><?=h($u['nombre_completo'])?></div></div><div class="col-md-6"><strong>Estado</strong><div><?=h(ucfirst(str_replace('_',' ',$t['estado'])))?></div></div><div class="col-md-6"><strong>Analista</strong><div><?=h($t['analista']?:'Sin asignar')?></div></div></div><a href="mis_tickets.php" class="btn btn-outline-secondary mt-4">Volver</a></div></div></div></div></div></body></html>